from flask import Blueprint, render_template, request, redirect, url_for
from app.models.note import Note
from app.database import db

notes_bp = Blueprint('notes', __name__)

@notes_bp.route('/', methods=['GET'])
def home():
    notes = Note.query.all()
    return render_template('index.html', notes=notes)

@notes_bp.route('/add', methods=['POST'])
def add_note():
    note_content = request.form.get('content')
    if note_content:
        new_note = Note(content=note_content)
        db.session.add(new_note)
        db.session.commit()
    return redirect(url_for('notes.home'))

@notes_bp.route('/delete/<int:note_id>', methods=['POST'])
def delete_note(note_id):
    note = Note.query.get(note_id)
    if note:
        db.session.delete(note)
        db.session.commit()
    return redirect(url_for('notes.home'))

/* static/style.css */
/* CSS for styling the application */

/* General styling */
body {
    font-family: Arial, sans-serif;
    margin: 0;
    padding: 0;
    background-color: #f8f9fa;
    color: #343a40;
}

/* Header styling */
header {
    background-color: #007bff;
    color: white;
    padding: 10px 20px;
    text-align: center;
    font-size: 1.5em;
}

/* Main container */
.container {
    max-width: 800px;
    margin: 20px auto;
    background: #ffffff;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
    border-radius: 8px;
    padding: 20px;
}

/* Form styling */
form {
    margin-bottom: 20px;
}

form input[type="text"],
form textarea {
    width: 100%;
    padding: 10px;
    margin: 10px 0;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 1em;
    box-sizing: border-box;
}

form button {
    background-color: #007bff;
    color: white;
    border: none;
    padding: 10px 20px;
    font-size: 1em;
    border-radius: 4px;
    cursor: pointer;
}

form button:hover {
    background-color: #0056b3;
}

/* Note list styling */
.notes-list {
    list-style: none;
    padding: 0;
}

.notes-list li {
    background-color: #f8f9fa;
    border: 1px solid #ced4da;
    margin: 10px 0;
    padding: 10px;
    border-radius: 4px;
}

.notes-list li h3 {
    margin: 0;
    font-size: 1.2em;
    color: #007bff;
}

.notes-list li p {
    margin: 5px 0 0;
    font-size: 1em;
    color: #343a40;
}

/* Footer styling */
footer {
    text-align: center;
    padding: 10px;
    background-color: #343a40;
    color: white;
    position: fixed;
    bottom: 0;
    width: 100%;
    font-size: 0.9em;
}

